<?php
require_once __DIR__.'/publishing_service.php';$autorPerfil=(int)($autorPerfil??$id_user);$gerenciar=$gerenciar??true;
$stmt=$conn->prepare("SELECT l.*,p.estado,v.publicada_em,p.atualizado_em,pr.nome_preferencia FROM publicacao_obra p JOIN livro l USING(id_livro) JOIN versao_publicacao v ON v.id=p.id_versao_atual LEFT JOIN preferencia_livro pl ON pl.id_livro=l.id_livro LEFT JOIN preferencia pr ON pr.id_preferencia=pl.id_preferencia WHERE p.id_autor=? AND p.estado='publicado' AND p.retirado_em IS NULL AND l.visibilidade='publico' ORDER BY v.publicada_em DESC");$stmt->execute([$autorPerfil]);$obrasPerfil=$stmt->fetchAll();
?><section class="published-profile"><div class="aba-topo"><h2>Livros publicados</h2><?php if($gerenciar):?><a class="button-perfil" href="minhas_obras.php">Minhas obras</a><?php endif;?></div><div class="published-book-grid"><?php foreach($obrasPerfil as $publicada):?><article><a href="visao_livro.php?id_livro=<?=(int)$publicada['id_livro']?>"><img src="<?=eObra($publicada['capa_url']?:'../img/livro-sem-capa.svg')?>" alt="Capa de <?=eObra($publicada['titulo_livro'])?>" width="100" height="150" loading="lazy"><h3><?=eObra($publicada['titulo_livro'])?></h3></a><p><?=eObra($publicada['nome_preferencia'])?> · <?=(int)$publicada['class_ind']?:'Livre'?></p><p><?=eObra(mb_strimwidth($publicada['sinopse_livro']??'',0,160,'…'))?></p><small>Publicado em <?=date('d/m/Y',strtotime($publicada['data_publi']))?> · Atualizado em <?=date('d/m/Y',strtotime($publicada['publicada_em']))?></small></article><?php endforeach;?></div><?php if(!$obrasPerfil):?><p>Ainda não há livros publicados.</p><?php endif;?></section>
